output_text:
[
  {
    "id": "geom_no_cart_single_file",
    "text": "Shopping carts must not be taken into single-file shelf aisles.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "adjShelf"
          ]
        },
        "cartInSingleFileAisle": {
          "and": [
            "hasCart",
            "singleFileAisle"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": "cartInSingleFileAisle"
    }
  },
  {
    "id": "geom_no_push_cart_into_single_file",
    "text": "It is forbidden to push a cart from a wider aisle into a single-file aisle.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "adjShelf"
          ]
        },
        "notSingleFileAisle": {
          "not": "singleFileAisle"
        }
      },
      "events": {
        "pushCartIntoSingleFileAisle": {
          "pre": {
            "and": [
              "hasCart",
              "notSingleFileAisle",
              "MOVE"
            ]
          },
          "post": {
            "and": [
              "hasCart",
              "singleFileAisle"
            ]
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "pushCartIntoSingleFileAisle"
    }
  },
  {
    "id": "geom_drop_cart_before_top_aisle",
    "text": "Before walking north from a top-aisle parking bay into a single-file aisle, the agent must first leave the cart at the bay.",
    "abstraction": {
      "state_properties": {
        "topAisleParkingBay": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "atBayWithCart": {
          "and": [
            "topAisleParkingBay",
            "hasCart"
          ]
        },
        "singleFileAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "adjShelf"
          ]
        }
      },
      "events": {
        "dropCartAtTopAisleBay": {
          "pre": {
            "and": [
              "topAisleParkingBay",
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "and": [
              "topAisleParkingBay",
              {
                "not": "hasCart"
              }
            ]
          }
        },
        "enterTopSingleFileAisle": {
          "pre": {
            "and": [
              "topAisleParkingBay",
              "N"
            ]
          },
          "post": "singleFileAisle"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "enterTopSingleFileAisle",
      "discharge": "dropCartAtTopAisleBay"
    }
  },
  {
    "id": "geom_no_north_push_from_parking_bay",
    "text": "At designated top-aisle parking bays, pushing the cart north toward the single-file aisle is prohibited.",
    "abstraction": {
      "state_properties": {
        "topAisleParkingBay": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "cartAtTopAisleParkingBay": {
          "and": [
            "topAisleParkingBay",
            "hasCart"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "cartAtTopAisleParkingBay",
          "N"
        ]
      }
    }
  },
  {
    "id": "geom_retrieve_cart_after_cartless_shelf_visit",
    "text": "After taking an item while cartless in a single-file aisle, the agent must return to a parking bay and retrieve the cart.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "adjShelf"
          ]
        },
        "topAisleParkingBay": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "cartlessShelfInteractionInSingleFileAisle": {
          "pre": {
            "and": [
              "singleFileAisle",
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": null
        },
        "retrieveCartAtParkingBay": {
          "pre": {
            "and": [
              "topAisleParkingBay",
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": {
            "and": [
              "topAisleParkingBay",
              "hasCart"
            ]
          }
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "cartlessShelfInteractionInSingleFileAisle",
      "discharge": "retrieveCartAtParkingBay"
    }
  },
  {
    "id": "geom_no_abandon_cart_after_parking",
    "text": "Whenever the agent parks the cart at a top-aisle bay, they are obliged to retrieve a cart before leaving the store.",
    "abstraction": {
      "state_properties": {
        "topAisleParkingBay": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "parkCartAtTopAisleBay": {
          "pre": {
            "and": [
              "topAisleParkingBay",
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "and": [
              "topAisleParkingBay",
              {
                "not": "hasCart"
              }
            ]
          }
        },
        "retrieveCartAtTopAisleBay": {
          "pre": {
            "and": [
              "topAisleParkingBay",
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": {
            "and": [
              "topAisleParkingBay",
              "hasCart"
            ]
          }
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "parkCartAtTopAisleBay",
      "discharge": "retrieveCartAtTopAisleBay"
    }
  },
  {
    "id": "geom_cart_required_for_non_single_file_shelf_pickup",
    "text": "Shelf interactions outside the single-file aisles must be done while holding or pushing the cart.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "adjShelf"
          ]
        },
        "ordinaryShelfPickupZone": {
          "and": [
            "adjShelf",
            {
              "not": "singleFileAisle"
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "ordinaryShelfPickupZone",
          "INTERACT",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "geom_no_cartless_wide_aisle_travel",
    "text": "Except at the entrance/cart rack, a parking bay, or inside a single-file aisle, the agent should not travel around the store without the cart.",
    "abstraction": {
      "state_properties": {
        "entranceOrCartRack": {
          "or": [
            "at(0,7)",
            "at(1,7)"
          ]
        },
        "topAisleParkingBay": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "singleFileAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "adjShelf"
          ]
        },
        "allowedCartlessPlace": {
          "or": [
            "entranceOrCartRack",
            "topAisleParkingBay",
            "singleFileAisle"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          {
            "not": "hasCart"
          },
          {
            "not": "allowedCartlessPlace"
          }
        ]
      }
    }
  }
]
